// Isolation test (OS-12) — construct Samples with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import type { Currency, Unit } from "../src/catalog/index.js";
import { LineageReader } from "../src/facts/index.js";
import { RevisionLog, Samples, type ConditionIdentity } from "../src/condition/index.js";
import { factWorld, never } from "./support/fact-world.js";

const u = "u1" as Unit;
const [c0, c1] = ["c0", "c1"] as unknown as readonly [Currency, Currency];
const setup = "setup" as ConditionIdentity;

/** u committed at c0, then drew one candidate at c1 under `setup`. */
function world() {
  const w = factWorld({ currencies: ["c0", "c1"], invalidations: never });
  w.commitAt(u, c0);
  w.drawAt(u, c1);
  const parts = { candidates: w.candidates, draws: w.draws, revisions: new RevisionLog({ record: w.record }), lineage: new LineageReader({ record: w.record }) };
  return { ...w, parts };
}

describe("Samples in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { parts } = world();
    for (const missing of Object.keys(parts)) expect(() => new Samples({ ...parts, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { parts } = world();
    for (const slot of Object.keys(parts)) expect(() => new Samples({ ...parts, [slot]: {} } as never), slot).toThrow();
  });

  it("of answers differently when candidates differs", () => {
    const w = world();
    const h = w.record.noise();
    expect(new Samples(w.parts).of(u, c1, setup).compute(h)).not.toEqual(new Samples({ ...w.parts, candidates: { candidatesAsOf: () => [] } }).of(u, c1, setup).compute(h));
  });

  it("of answers differently when revisions and lineage differ (the closure)", () => {
    const w = world();
    const s = w.drawAt(u, c1);
    const k = w.commitments.commit(s, "HUMAN");
    const h = w.record.noise();
    const quiet = { revisions: () => [], acceptedBy: () => [] };
    expect(new Samples(w.parts).of(u, c1, setup).compute(h)).not.toEqual(new Samples({ ...w.parts, lineage: { acceptedBy: quiet.acceptedBy } }).of(u, c1, setup).compute(h));
    const revisions = new RevisionLog({ record: w.record });
    revisions.revise(u, c1, "other" as ConditionIdentity, "HUMAN");
    const later = w.record.noise();
    const noLineage = { ...w.parts, lineage: { acceptedBy: quiet.acceptedBy } };
    expect(new Samples(noLineage).of(u, c1, setup).compute(later)).not.toEqual(new Samples({ ...noLineage, revisions: { revisions: quiet.revisions } }).of(u, c1, setup).compute(later));
    expect(k.payload.candidate).toBe(s.at);
  });

  it("samplesFor answers differently when draws differs", () => {
    const w = world();
    const h = w.record.noise();
    expect(new Samples(w.parts).samplesFor(u, c1, h)).not.toEqual(new Samples({ ...w.parts, draws: { drawsAsOf: () => [] } }).samplesFor(u, c1, h));
  });
});
